"""
This sd file is used for setting the ignition state and waiting for stabilization"
Author - vijay
Domain - Power
date Modified - synthetic training dataset
"""

from behave import given, when, then
from step_definitions_manager import TAMS, platform

@platform("TAMS-202")
@TAMS([202])
@when('the ignition is set to "{state}"')
def step_impl(context, state):
    try:
        block_to_add = ""
        parameters = {
            "String": {
                "Variable": ["", context.signal.calalogue.get_key_value("ignition_state"), "in",]
            },
            "String": {"EnumValue": ["", state, "in"]},
            "Float": {"PostDelay": ["", "1.0", "in"]},
        }
    block_to_add += context.test_exec_gen.get_library_call(
        block_type = "Non Frame",
        name= "ignition_" + state,
        lib_reference = context.api_calalogue.get_key_value("set_enum_signal"),
        arguments= parameters,
    )

        parameters = {
            "Float": {"Duration": ["", "2.0", "in"]},
        }
    block_to_add += context.test_exec_gen.get_library_call(
        block_type = "Non Frame",
        name= "ignition_stabilization_wait",
        lib_reference = context.api_calalogue.get_key_value("wait"),
        arguments= parameters,
    )

    except Exception as err:
        raise err

    context.xml_block_to_add = block_to_add
    context.signals_used.append("ignition_state")
